blocks.code:
body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

h1, h2 {
  font-family: Georgia, "Times New Roman", serif;
}

code {
  font-family: ui-monospace, "Cascadia Code", Consolas, monospace;
  font-size: 0.95em;
}

@font-face {
  font-family: "Inter";
  src: url("../fonts/inter-variable.woff2") format("woff2");
  font-weight: 100 900;      /* the file covers every weight */
  font-style: normal;
  font-display: swap;
}

body {
  font-family: "Inter", system-ui, sans-serif;
}

h1 {
  font-size: 2.25rem;
  font-weight: 800;
}

h2 {
  font: italic 600 1.25rem/1.3 Georgia, serif;  /* style weight size/line-height family */
}

strong {
  font-weight: 600;   /* a lighter bold than the default 700 */
}

body {
  line-height: 1.6;
}

h1, h2 {
  line-height: 1.15;
}

p {
  max-width: 60ch;
  margin: 0 0 1rem;
}

h2 {
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.9rem;
}

a {
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
}

li {
  max-width: 9ch;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;   /* "Second item" becomes "Second i…" */
}
